export interface BeatData {
  time: number;
  energy: number;
}

export interface AnalysisSettings {
  threshold: number;
  minInterval: number;
  lowFreq: number;
  highFreq: number;
  smoothing: number;
}

export interface AnalysisResult {
  bpm: number;
  beats: BeatData[];
  duration: number;
  peaks: number[];
  audioBuffer: AudioBuffer | null;
  settings: AnalysisSettings;
}

export interface VideoBuffer {
  frames: ImageBitmap[];
  fps: number;
  width: number;
  height: number;
  duration: number;
}

export interface VideoSegment {
  id: string;
  start: number;
  end: number;
  speed: number;
  isReversed: boolean;
}

export interface ProcessingStatus {
  step: string;
  progress: number;
  isProcessing: boolean;
}

export interface VideoSource {
  id: string;
  name: string;
  buffer: VideoBuffer;
  media: any;
  segment: VideoSegment;
  thumbnail: string; // data URL of the first frame
}

import React, { useEffect, useRef } from 'react';
import { VideoBuffer } from '../types';

interface ImpulseCanvasProps {
  buffer: VideoBuffer | null;
  progress: number; // 0 to 1
  intensity: number; // 0 to 1 for visual feedback
}

export const ImpulseCanvas: React.FC<ImpulseCanvasProps> = ({ buffer, progress, intensity }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!buffer || !canvasRef.current) return;
    const ctx = canvasRef.current.getContext('2d', { alpha: false });
    if (!ctx) return;

    const frameIndex = Math.min(
      Math.max(Math.floor(progress * (buffer.frames.length - 1)), 0),
      buffer.frames.length - 1
    );

    const frame = buffer.frames[frameIndex];
    if (frame) {
      ctx.drawImage(frame, 0, 0, canvasRef.current.width, canvasRef.current.height);

      // Optional: Flash overlay on high intensity
      if (intensity > 0.8) {
        ctx.fillStyle = `rgba(255, 255, 255, ${(intensity - 0.8) * 0.5})`;
        ctx.fillRect(0, 0, canvasRef.current.width, canvasRef.current.height);
      }
    }
  }, [buffer, progress, intensity]);

  if (!buffer) return null;

  return (
    <div className="relative aspect-video w-full bg-black rounded-2xl overflow-hidden shadow-2xl border border-white/5 mx-auto">
      <canvas
        ref={canvasRef}
        width={buffer.width}
        height={buffer.height}
        className="w-full h-full object-contain"
      />
      <div className="absolute bottom-4 left-4 right-4 h-1 bg-white/10 rounded-full overflow-hidden">
        <div 
          className="h-full bg-white transition-all duration-75 ease-out"
          style={{ width: `${progress * 100}%` }}
        />
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { Trash2, Minus, Plus } from 'lucide-react';
import { VideoSegment } from '../types';

interface SegmentItemProps {
  segment: VideoSegment;
  index: number;
  maxDuration: number;
  onRemove: (id: string) => void;
  onDuplicate: (id: string) => void;
  onUpdate: (id: string, updates: Partial<VideoSegment>) => void;
}

const NUDGE_STEP = 0.01;

export const SegmentItem: React.FC<SegmentItemProps> = ({ 
  segment, 
  index, 
  maxDuration,
  onRemove, 
  onDuplicate, 
  onUpdate
}) => {
  const trackRef = useRef<HTMLDivElement>(null);
  const [dragging, setDragging] = useState<'start' | 'end' | 'range' | null>(null);
  const dragOriginRef = useRef({ x: 0, start: 0, end: 0 });

  const getPercent = (value: number) => maxDuration > 0 ? (value / maxDuration) * 100 : 0;

  const getValueFromX = (clientX: number) => {
    if (!trackRef.current) return 0;
    const rect = trackRef.current.getBoundingClientRect();
    const pct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    return Math.round(pct * maxDuration * 100) / 100;
  };

  const nudge = (which: 'start' | 'end', direction: 1 | -1) => {
    if (which === 'start') {
      const newStart = Math.round((segment.start + direction * NUDGE_STEP) * 100) / 100;
      onUpdate(segment.id, { start: Math.max(0, Math.min(newStart, segment.end - 0.01)) });
    } else {
      const newEnd = Math.round((segment.end + direction * NUDGE_STEP) * 100) / 100;
      onUpdate(segment.id, { end: Math.min(maxDuration, Math.max(newEnd, segment.start + 0.01)) });
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!trackRef.current) return;
    const rect = trackRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const startPx = (segment.start / maxDuration) * rect.width;
    const endPx = (segment.end / maxDuration) * rect.width;
    const segWidthPx = endPx - startPx;
    const HANDLE_HIT = 6; // px from the handle line

    // Shift+click always moves the whole segment
    if (e.shiftKey && x >= startPx - HANDLE_HIT && x <= endPx + HANDLE_HIT) {
      setDragging('range');
      dragOriginRef.current = { x: e.clientX, start: segment.start, end: segment.end };
      e.preventDefault();
      return;
    }

    // For small segments (<40px), prioritize range drag if inside bounds
    if (segWidthPx < 40 && x >= startPx && x <= endPx) {
      setDragging('range');
      dragOriginRef.current = { x: e.clientX, start: segment.start, end: segment.end };
      e.preventDefault();
      return;
    }

    // Normal-sized segments: handles get hit zones, middle is range drag
    if (Math.abs(x - startPx) <= HANDLE_HIT) {
      setDragging('start');
    } else if (Math.abs(x - endPx) <= HANDLE_HIT) {
      setDragging('end');
    } else if (x > startPx && x < endPx) {
      setDragging('range');
      dragOriginRef.current = { x: e.clientX, start: segment.start, end: segment.end };
    }

    e.preventDefault();
  };

  useEffect(() => {
    if (!dragging) return;

    const handleMouseMove = (e: MouseEvent) => {
      if (dragging === 'start') {
        const newStart = Math.min(getValueFromX(e.clientX), segment.end - 0.01);
        onUpdate(segment.id, { start: Math.max(0, newStart) });
      } else if (dragging === 'end') {
        const newEnd = Math.max(getValueFromX(e.clientX), segment.start + 0.01);
        onUpdate(segment.id, { end: Math.min(maxDuration, newEnd) });
      } else if (dragging === 'range') {
        const dx = e.clientX - dragOriginRef.current.x;
        if (!trackRef.current) return;
        const rect = trackRef.current.getBoundingClientRect();
        const dt = (dx / rect.width) * maxDuration;
        const span = dragOriginRef.current.end - dragOriginRef.current.start;

        let newStart = dragOriginRef.current.start + dt;
        let newEnd = dragOriginRef.current.end + dt;

        if (newStart < 0) { newStart = 0; newEnd = span; }
        if (newEnd > maxDuration) { newEnd = maxDuration; newStart = maxDuration - span; }

        onUpdate(segment.id, { 
          start: Math.round(newStart * 100) / 100, 
          end: Math.round(newEnd * 100) / 100 
        });
      }
    };

    const handleMouseUp = () => setDragging(null);

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [dragging, segment, maxDuration, onUpdate]);

  const startPct = getPercent(segment.start);
  const endPct = getPercent(segment.end);

  return (
    <div className="segment-card">
      {/* Time readouts */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <button onClick={() => nudge('start', -1)} style={{ all: 'unset', cursor: 'pointer', padding: '0 2px', color: 'var(--text-muted)' }}><Minus size={8} /></button>
          <span className="setting-value" style={{ fontSize: '10px', minWidth: 44, textAlign: 'center' }}>{segment.start.toFixed(2)}s</span>
          <button onClick={() => nudge('start', 1)} style={{ all: 'unset', cursor: 'pointer', padding: '0 2px', color: 'var(--text-muted)' }}><Plus size={8} /></button>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <button onClick={() => nudge('end', -1)} style={{ all: 'unset', cursor: 'pointer', padding: '0 2px', color: 'var(--text-muted)' }}><Minus size={8} /></button>
          <span className="setting-value" style={{ fontSize: '10px', minWidth: 44, textAlign: 'center' }}>{segment.end.toFixed(2)}s</span>
          <button onClick={() => nudge('end', 1)} style={{ all: 'unset', cursor: 'pointer', padding: '0 2px', color: 'var(--text-muted)' }}><Plus size={8} /></button>
        </div>
      </div>

      {/* Range slider */}
      <div 
        ref={trackRef}
        className="relative cursor-pointer select-none"
        style={{ height: 24, cursor: dragging === 'range' ? 'grabbing' : 'pointer' }}
        onMouseDown={handleMouseDown}
      >
        {/* Track line */}
        <div style={{ position: 'absolute', top: '50%', transform: 'translateY(-50%)', left: 0, right: 0, height: 2, background: 'var(--border)', borderRadius: 1 }} />
        {/* Active region — filled bar */}
        <div style={{
          position: 'absolute', top: '50%', transform: 'translateY(-50%)', borderRadius: 1,
          left: `${startPct}%`, width: `${endPct - startPct}%`,
          height: dragging === 'range' ? 8 : 4,
          background: dragging === 'range' ? 'var(--accent)' : 'var(--accent-dim)',
          cursor: 'grab',
          transition: dragging ? 'none' : 'height 0.1s',
        }} />
        {/* Start handle */}
        <div style={{
          position: 'absolute', top: '50%', transform: 'translate(-50%, -50%)', left: `${startPct}%`,
          width: 3, height: dragging === 'start' ? 18 : 12,
          background: dragging === 'start' ? 'var(--accent)' : 'var(--text-dim)', borderRadius: 1,
          cursor: 'col-resize',
          transition: dragging ? 'none' : 'height 0.1s',
        }} />
        {/* End handle */}
        <div style={{
          position: 'absolute', top: '50%', transform: 'translate(-50%, -50%)', left: `${endPct}%`,
          width: 3, height: dragging === 'end' ? 18 : 12,
          background: dragging === 'end' ? 'var(--accent)' : 'var(--text-dim)', borderRadius: 1,
          cursor: 'col-resize',
          transition: dragging ? 'none' : 'height 0.1s',
        }} />
      </div>

      {/* Hint */}
      <div style={{ fontSize: '7px', color: 'var(--text-muted)', marginTop: 2, textAlign: 'right', letterSpacing: '0.05em' }}>
        shift+drag to move · arrows to nudge
      </div>

      {/* Controls row */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 6 }}>
        <select 
          value={segment.speed}
          onChange={(e) => onUpdate(segment.id, { speed: parseFloat(e.target.value) })}
        >
          <option value="0.5">0.5x</option>
          <option value="1">1.0x</option>
          <option value="1.5">1.5x</option>
          <option value="2">2.0x</option>
        </select>

        <button 
          onClick={() => onUpdate(segment.id, { isReversed: !segment.isReversed })}
          className="action-btn"
          style={{ 
            padding: '2px 8px',
            color: segment.isReversed ? 'var(--accent)' : 'var(--text-muted)',
            borderColor: segment.isReversed ? 'var(--accent-dim)' : 'var(--border)',
          }}
        >
          {segment.isReversed ? 'rev' : 'fwd'}
        </button>

        <button 
          onClick={() => onRemove(segment.id)}
          style={{ all: 'unset', cursor: 'pointer', padding: 2, color: 'var(--text-muted)' }}
          title="Remove"
        >
          <Trash2 size={10} />
        </button>
      </div>
    </div>
  );
};

import React from 'react';
import { Info } from 'lucide-react';
import { AnalysisSettings } from '../types';

interface SettingsPanelProps {
  settings: AnalysisSettings;
  onChange: (settings: AnalysisSettings) => void;
  onReanalyze?: () => void;
  disabled?: boolean;
}

export const SettingsPanel: React.FC<SettingsPanelProps> = ({ 
  settings, 
  onChange, 
  onReanalyze,
  disabled 
}) => {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      {/* Spectral Analysis */}
      <div>
        <div className="ascii-divider">├─ spectral</div>

        <div className="setting-row">
          <span className="setting-label">low hz</span>
          <span className="setting-value">{settings.lowFreq}</span>
        </div>
        <input
          type="range"
          min="20"
          max="2000"
          step="10"
          value={settings.lowFreq}
          onChange={(e) => onChange({ ...settings, lowFreq: parseInt(e.target.value) })}
        />

        <div className="setting-row" style={{ marginTop: 6 }}>
          <span className="setting-label">high hz</span>
          <span className="setting-value">{settings.highFreq}</span>
        </div>
        <input
          type="range"
          min="200"
          max="15000"
          step="100"
          value={settings.highFreq}
          onChange={(e) => onChange({ ...settings, highFreq: parseInt(e.target.value) })}
        />

        <div className="setting-row" style={{ marginTop: 6 }}>
          <span className="setting-label">sensitivity</span>
          <span className="setting-value">{(6 - settings.threshold).toFixed(2)}</span>
        </div>
        <input
          type="range"
          min="1.0"
          max="5.0"
          step="0.05"
          value={6 - settings.threshold}
          onChange={(e) => onChange({ ...settings, threshold: 6 - parseFloat(e.target.value) })}
        />

        <div className="setting-row" style={{ marginTop: 6 }}>
          <span className="setting-label">min gap</span>
          <span className="setting-value">{settings.minInterval.toFixed(2)}s</span>
        </div>
        <input
          type="range"
          min="0.05"
          max="1.0"
          step="0.05"
          value={settings.minInterval}
          onChange={(e) => onChange({ ...settings, minInterval: parseFloat(e.target.value) })}
        />

        <div style={{ fontSize: '8px', color: 'var(--text-muted)', marginTop: 4 }}>
          kick: 40-150 · snare: 800-2500
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { VideoBuffer } from '../types';
import { VideoSegment } from '../types';
import { applyEffect, EFFECT, EffectId, ANIMATED_EFFECTS } from '../effects';

interface TimelinePreviewProps {
  buffer: VideoBuffer;
  segments: VideoSegment[];
  impulse: number; // 0 to 1, drives the scrub position
  intensity: number;
  isFullscreen?: boolean;
  effect?: EffectId;
  canvasRef?: React.RefObject<HTMLCanvasElement | null>;
}

export const TimelinePreview: React.FC<TimelinePreviewProps> = ({ 
  buffer, 
  segments, 
  impulse, 
  intensity, 
  isFullscreen, 
  effect = EFFECT.NONE,
  canvasRef: externalCanvasRef
}) => {
  const internalCanvasRef = useRef<HTMLCanvasElement>(null);
  const canvasRef = externalCanvasRef || internalCanvasRef;
  const [vfxTick, setVfxTick] = useState(0);
  const [animTick, setAnimTick] = useState(0);

  // Force a redraw when VFX effect parameters change (e.g. ASCII block size).
  useEffect(() => {
    const onChange = () => setVfxTick(t => t + 1);
    window.addEventListener('vfx-effects-changed', onChange);
    return () => window.removeEventListener('vfx-effects-changed', onChange);
  }, []);

  // For time-based effects (kaleidoscope spin, glitch noise), tick at rAF
  // cadence so the effect animates even while playback is paused.
  useEffect(() => {
    if (!ANIMATED_EFFECTS.has(effect)) return;
    let raf = 0;
    const loop = () => {
      setAnimTick(t => (t + 1) % 1_000_000);
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [effect]);

  // Use raw durations for the timeline base so speed can act as a multiplier
  const totalTimelineDuration = segments.reduce((acc, s) => acc + (s.end - s.start), 0);

  const drawFrame = (progress: number) => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d', { alpha: false });
    if (!canvas || !ctx || !buffer.frames.length) return;

    const targetTime = progress * totalTimelineDuration;

    // Find which segment we are currently in
    let elapsed = 0;
    let currentSegment = segments[0] || { start: 0, end: buffer.duration, speed: 1, isReversed: false };
    let timeInSegment = 0;

    for (const seg of segments) {
      const segClipLen = seg.end - seg.start;
      if (targetTime <= elapsed + segClipLen) {
        currentSegment = seg;
        // Apply speed to the relative progress within the segment, with modulo for looping
        timeInSegment = ((targetTime - elapsed) * seg.speed) % segClipLen;
        break;
      }
      elapsed += segClipLen;
      currentSegment = seg;
      timeInSegment = ((targetTime - elapsed) * seg.speed) % segClipLen;
    }

    // Calculate source frame index
    let sourceTime;
    if (currentSegment.isReversed) {
      sourceTime = currentSegment.end - timeInSegment;
    } else {
      sourceTime = currentSegment.start + timeInSegment;
    }

    sourceTime = Math.max(0, Math.min(sourceTime, buffer.duration));

    const frameIndex = Math.min(
      Math.max(Math.floor(sourceTime * buffer.fps), 0),
      buffer.frames.length - 1
    );

    const frame = buffer.frames[frameIndex];
    if (frame) {
      ctx.drawImage(frame, 0, 0, canvas.width, canvas.height);

      if (intensity > 0.8) {
        ctx.fillStyle = `rgba(255, 255, 255, ${(intensity - 0.8) * 0.4})`;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }

      // Post-processing effect (read after the underlying frame is drawn)
      if (effect !== EFFECT.NONE) {
        applyEffect(ctx, effect);
      }
    }
  };

  useEffect(() => {
    drawFrame(impulse);
  }, [impulse, buffer, segments, intensity, effect, vfxTick, animTick]);

  return (
    <div className="relative w-full h-full flex items-center justify-center" style={{ background: '#000' }}>
      <canvas
        ref={canvasRef}
        width={buffer.width}
        height={buffer.height}
        style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block' }}
      />
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Music } from 'lucide-react';
import { AnalysisResult } from '../types';

interface WaveformVisualizerProps {
  analysis: AnalysisResult | null;
  currentTime: number;
  trimRange: [number, number];
  onTrimChange: (range: [number, number]) => void;
  onSeek: (time: number) => void;
  onSelect?: () => void;
}

export const WaveformVisualizer: React.FC<WaveformVisualizerProps> = ({ 
  analysis, 
  currentTime, 
  trimRange,
  onTrimChange,
  onSeek,
  onSelect
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDragging, setIsDragging] = useState<'start' | 'end' | 'seek' | null>(null);
  const [resizeTick, setResizeTick] = useState(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ro = new ResizeObserver(() => setResizeTick(t => t + 1));
    ro.observe(canvas);
    return () => ro.disconnect();
  }, []);

  // X is in CSS pixels (relative to the canvas), matching the rendered DOM size.
  const getXFromTime = (time: number) => {
    if (!analysis || !canvasRef.current) return 0;
    const rect = canvasRef.current.getBoundingClientRect();
    return (time / analysis.duration) * rect.width;
  };

  const getTimeFromX = (x: number) => {
    if (!analysis || !canvasRef.current) return 0;
    const rect = canvasRef.current.getBoundingClientRect();
    return Math.max(0, Math.min(analysis.duration, (x / rect.width) * analysis.duration));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!analysis) {
      onSelect?.();
      return;
    }
    if (!canvasRef.current) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const time = getTimeFromX(x);

    const startX = getXFromTime(trimRange[0]) / (canvasRef.current.width / rect.width);
    const endX = getXFromTime(trimRange[1]) / (canvasRef.current.width / rect.width);

    if (Math.abs(x - startX) < 12) {
      setIsDragging('start');
    } else if (Math.abs(x - endX) < 12) {
      setIsDragging('end');
    } else {
      setIsDragging('seek');
      onSeek(time);
    }
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging || !analysis || !canvasRef.current) return;
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const time = getTimeFromX(x);

      if (isDragging === 'start') {
        onTrimChange([Math.min(time, trimRange[1] - 0.1), trimRange[1]]);
      } else if (isDragging === 'end') {
        onTrimChange([trimRange[0], Math.max(time, trimRange[0] + 0.1)]);
      } else if (isDragging === 'seek') {
        onSeek(time);
      }
    };

    const handleMouseUp = () => setIsDragging(null);

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, analysis, trimRange, onTrimChange, onSeek]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !analysis || !analysis.audioBuffer) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Match backing store to actual rendered size × DPR for crisp 1px lines
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    const w = Math.max(1, Math.floor(rect.width));
    const h = Math.max(1, Math.floor(rect.height));
    if (canvas.width !== w * dpr || canvas.height !== h * dpr) {
      canvas.width = w * dpr;
      canvas.height = h * dpr;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const { audioBuffer, beats } = analysis;
    const data = audioBuffer.getChannelData(0);
    const step = Math.max(1, Math.ceil(data.length / w));
    const amp = h / 2;

    ctx.clearRect(0, 0, w, h);

    // Background — matches the video screen-area
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, w, h);

    const startX = (trimRange[0] / analysis.duration) * w;
    const endX = (trimRange[1] / analysis.duration) * w;

    // Compute peak envelope per column
    const peaks: number[] = new Array(w);
    for (let i = 0; i < w; i++) {
      let maxAbs = 0;
      for (let j = 0; j < step; j++) {
        const v = Math.abs(data[(i * step) + j] ?? 0);
        if (v > maxAbs) maxAbs = v;
      }
      peaks[i] = maxAbs;
    }

    // Thin solid envelope — top and bottom mirrored polylines
    const drawEnvelope = (color: string, fromX: number, toX: number) => {
      if (toX <= fromX) return;
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let i = fromX; i <= toX; i++) {
        const y = amp - peaks[i] * amp;
        if (i === fromX) ctx.moveTo(i + 0.5, y);
        else ctx.lineTo(i + 0.5, y);
      }
      ctx.stroke();
      ctx.beginPath();
      for (let i = fromX; i <= toX; i++) {
        const y = amp + peaks[i] * amp;
        if (i === fromX) ctx.moveTo(i + 0.5, y);
        else ctx.lineTo(i + 0.5, y);
      }
      ctx.stroke();
    };

    const sx = Math.floor(startX);
    const ex = Math.ceil(endX);
    drawEnvelope('#2a2a2a', 0, sx);
    drawEnvelope('#2a8068', sx, ex);
    drawEnvelope('#2a2a2a', ex, w - 1);

    // Beat marks — thin solid lines
    beats.forEach(beat => {
      const x = (beat.time / analysis.duration) * w;
      const isInTrim = x >= startX && x <= endX;
      ctx.beginPath();
      ctx.strokeStyle = isInTrim ? '#5af0c8' : 'rgba(90, 240, 200, 0.18)';
      ctx.lineWidth = 1;
      ctx.moveTo(Math.round(x) + 0.5, 0);
      ctx.lineTo(Math.round(x) + 0.5, h);
      ctx.stroke();
    });

    // Playhead
    const playheadX = (currentTime / analysis.duration) * w;
    ctx.beginPath();
    ctx.strokeStyle = '#5af0c8';
    ctx.lineWidth = 1.5;
    ctx.moveTo(playheadX, 0);
    ctx.lineTo(playheadX, h);
    ctx.stroke();

    // Handles
    const drawHandle = (x: number) => {
      ctx.fillStyle = 'rgba(200, 200, 200, 0.6)';
      ctx.fillRect(Math.round(x) - 0.5, 0, 1, h);
    };

    drawHandle(startX);
    drawHandle(endX);

  }, [analysis, currentTime, trimRange, resizeTick]);

  return (
    <div className="waveform-container" onMouseDown={handleMouseDown}>
      <canvas 
        ref={canvasRef} 
        width={800} 
        height={48} 
        style={{ width: '100%', height: '100%' }}
      />
    </div>
  );
};

