// Effect IDs
export const EFFECT = {
  NONE: 0,
  ASCII: 1,
  GLITCH: 2,
  KALEIDO: 3,
} as const;

export type EffectId = typeof EFFECT[keyof typeof EFFECT];

// Selectable effects (excludes NONE — that's the deactivated state).
// Each entry is shown in the sidebar's display section and bound to a single
// letter key. Pressing the key (or clicking the item) toggles the effect on/off.
export const EFFECTS: Array<{ id: EffectId; name: string; key: string }> = [
  { id: EFFECT.ASCII,   name: 'ASCII MATRIX', key: 'a' },
  { id: EFFECT.GLITCH,  name: 'GLITCH',       key: 'g' },
  { id: EFFECT.KALEIDO, name: 'KALEIDOSCOPE', key: 'k' },
];

// Effects that need continuous redraws even while paused (time-based animation,
// per-frame randomness). TimelinePreview runs a rAF loop while one is active.
export const ANIMATED_EFFECTS = new Set<EffectId>([EFFECT.GLITCH, EFFECT.KALEIDO]);

export const EFFECT_NAMES: Record<EffectId, string> = {
  [EFFECT.NONE]: 'NONE',
  [EFFECT.ASCII]: 'ASCII MATRIX',
  [EFFECT.GLITCH]: 'GLITCH',
  [EFFECT.KALEIDO]: 'KALEIDOSCOPE',
};

// Brightness ramp from darkest to brightest. A mix of punctuation, math/
// currency symbols, daggers, and Unicode block-elements gives the output a
// glitchy, terminal-corruption feel rather than a clean tone curve.
const ASCII_RAMP = " .'`\",:;~-_^+*<>/\\|?![]{}=#%@¦¤§¶µ¬±†‡░▒▓█";

/**
 * Apply a Matrix-flavored ASCII post-process to the canvas content.
 * Reads the current pixels, wipes to black, then redraws as green ASCII chars
 * sized to `blockSize` (each char represents one blockSize × blockSize patch).
 */
export function applyAsciiEffect(ctx: CanvasRenderingContext2D, blockSize: number) {
  const w = ctx.canvas.width;
  const h = ctx.canvas.height;
  if (w === 0 || h === 0 || blockSize < 1) return;

  const img = ctx.getImageData(0, 0, w, h);
  const data = img.data;

  const contrast = 1.5;
  const intercept = 128 * (1 - contrast);
  for (let i = 0; i < data.length; i += 4) {
    data[i]     = Math.max(0, Math.min(255, data[i] * contrast + intercept));
    data[i + 1] = Math.max(0, Math.min(255, data[i + 1] * contrast + intercept));
    data[i + 2] = Math.max(0, Math.min(255, data[i + 2] * contrast + intercept));
  }

  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, w, h);

  ctx.font = `bold ${blockSize}px 'JetBrains Mono', 'SF Mono', monospace`;
  ctx.textBaseline = 'top';
  ctx.textAlign = 'left';

  const ramp = ASCII_RAMP;
  const rampMax = ramp.length - 1;

  for (let by = 0; by < h; by += blockSize) {
    const yEnd = Math.min(by + blockSize, h);
    for (let bx = 0; bx < w; bx += blockSize) {
      const xEnd = Math.min(bx + blockSize, w);
      let sum = 0;
      let count = 0;
      for (let py = by; py < yEnd; py++) {
        const rowStart = py * w * 4;
        for (let px = bx; px < xEnd; px++) {
          const i = rowStart + px * 4;
          // Rec. 601 luminance
          sum += 0.299 * data[i] + 0.587 * data[i + 1] + 0.114 * data[i + 2];
          count++;
        }
      }
      const avg = sum / Math.max(1, count) / 255;          // 0..1
      const charIdx = Math.min(rampMax, Math.floor(avg * (rampMax + 1)));
      const ch = ramp[charIdx];
      // Matrix green; brightness modulates intensity for a phosphor feel.
      const g = Math.round(70 + avg * 185);                // 70..255
      const b = Math.round(g * 0.55);
      ctx.fillStyle = `rgb(0,${g},${b})`;
      ctx.fillText(ch, bx, by);
    }
  }
}

/**
 * Glitch effect — datamosh-style horizontal slab displacement plus an RGB-ish
 * chromatic split. Every call re-rolls the random offsets, so during playback
 * the glitch animates frame by frame.
 */
export function applyGlitchEffect(ctx: CanvasRenderingContext2D, intensity: number) {
  const w = ctx.canvas.width;
  const h = ctx.canvas.height;
  if (w === 0 || h === 0 || intensity <= 0) return;

  const buf = ctx.getImageData(0, 0, w, h);

  // Slab count + max shift scale with intensity (0..1)
  const slabCount = Math.round(2 + intensity * 14);
  const maxShift = w * (0.08 + intensity * 0.32);

  for (let i = 0; i < slabCount; i++) {
    const y = Math.floor(Math.random() * h);
    const slabH = Math.max(1, Math.floor(2 + Math.random() * Math.max(2, h * 0.08)));
    const slabH2 = Math.min(slabH, h - y);
    if (slabH2 <= 0) continue;
    const dx = Math.floor((Math.random() - 0.5) * 2 * maxShift);
    // Black out original strip so the displaced version reads as a "tear"
    ctx.fillStyle = '#000';
    ctx.fillRect(0, y, w, slabH2);
    // Place the displaced strip
    ctx.putImageData(buf, dx, 0, 0, y, w, slabH2);
  }

  // Chromatic split — redraw the original frame as a red-ish ghost shifted left
  // and a cyan-ish ghost shifted right, blended over.
  const splitMag = Math.round(intensity * 8) + 1;
  const off = document.createElement('canvas');
  off.width = w;
  off.height = h;
  const octx = off.getContext('2d');
  if (octx) {
    octx.putImageData(buf, 0, 0);
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.45;
    // Red ghost
    ctx.filter = 'saturate(0%) sepia(100%) hue-rotate(-50deg) saturate(800%)';
    ctx.drawImage(off, -splitMag, 0);
    // Cyan ghost
    ctx.filter = 'saturate(0%) sepia(100%) hue-rotate(150deg) saturate(800%)';
    ctx.drawImage(off, splitMag, 0);
    ctx.restore();
  }

  // Occasional thin scanline corruption — random bright lines
  const noiseLines = Math.round(intensity * 6);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.15)';
  for (let i = 0; i < noiseLines; i++) {
    const ny = Math.floor(Math.random() * h);
    ctx.fillRect(0, ny, w, 1);
  }
}

/**
 * Kaleidoscope — radial mirrored slices spinning over time. Each output wedge
 * clips a narrow source slice from the underlying frame; alternating wedges
 * reflect across the wedge centerline for the classic mirrored-petal pattern.
 * Drift is driven by Date.now so the pattern stays trippy on a paused frame
 * (the parent runs a rAF tick while a kaleido/animated effect is held).
 */
export function applyKaleidoscopeEffect(
  ctx: CanvasRenderingContext2D,
  segments: number,
  speed: number
) {
  const w = ctx.canvas.width;
  const h = ctx.canvas.height;
  if (w === 0 || h === 0 || segments < 2) return;

  // Snapshot current frame to off-screen, then wipe the visible canvas.
  const off = document.createElement('canvas');
  off.width = w;
  off.height = h;
  const octx = off.getContext('2d');
  if (!octx) return;
  octx.drawImage(ctx.canvas, 0, 0);

  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, w, h);

  const cx = w / 2;
  const cy = h / 2;
  const wedgeAngle = (Math.PI * 2) / segments;
  const radius = Math.hypot(w, h); // covers all corners regardless of rotation
  const rotation = (Date.now() * 0.0005 * speed) % (Math.PI * 2);

  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(rotation);

  for (let i = 0; i < segments; i++) {
    ctx.save();
    ctx.rotate(i * wedgeAngle);

    // Triangular wedge clip along the +X axis.
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.arc(0, 0, radius, -wedgeAngle / 2, wedgeAngle / 2);
    ctx.closePath();
    ctx.clip();

    // Mirror every other wedge so adjacent slices reflect.
    if (i % 2 === 1) ctx.scale(1, -1);

    ctx.drawImage(off, -cx, -cy);
    ctx.restore();
  }
  ctx.restore();
}

export function applyEffect(ctx: CanvasRenderingContext2D, effect: EffectId) {
  switch (effect) {
    case EFFECT.ASCII:
      applyAsciiEffect(ctx, VFX.asciiBlockSize.val);
      break;
    case EFFECT.GLITCH:
      applyGlitchEffect(ctx, VFX.glitchIntensity.val);
      break;
    case EFFECT.KALEIDO:
      applyKaleidoscopeEffect(
        ctx,
        Math.round(VFX.kaleidoSegments.val),
        VFX.kaleidoSpeed.val,
      );
      break;
    case EFFECT.NONE:
    default:
      break;
  }
}

