const generateThumbnail = (buffer: VideoBuffer): string => {
  const canvas = document.createElement('canvas');
  const scale = Math.min(1, 128 / buffer.width);
  canvas.width = Math.round(buffer.width * scale);
  canvas.height = Math.round(buffer.height * scale);
  const ctx = canvas.getContext('2d', { alpha: false });
  if (ctx && buffer.frames.length > 0) ctx.drawImage(buffer.frames[0], 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL('image/jpeg', 0.7);
};

