  };

  const pressEffect = (id: EffectId) => {
    if (heldEffectsRef.current.includes(id)) return;
    heldEffectsRef.current.push(id);
    setActiveEffect(id);
  };

  const releaseEffect = (id: EffectId) => {
    heldEffectsRef.current = heldEffectsRef.current.filter(x => x !== id);
    const top = heldEffectsRef.current[heldEffectsRef.current.length - 1];
    setActiveEffect(top ?? EFFECT.NONE);
  };

  const pressScanlines = (source: string) => {
    heldScanlinesRef.current.add(source);
    setShowScanlines(true);
  };

  const releaseScanlines = (source: string) => {
    heldScanlinesRef.current.delete(source);
    if (heldScanlinesRef.current.size === 0) setShowScanlines(false);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === ' ') { e.preventDefault(); togglePlayRef.current(); return; }
      const target = e.target as HTMLElement | null;
      const isTextField = target?.tagName === 'TEXTAREA' || target?.isContentEditable || (target?.tagName === 'INPUT' && /^(text|search|email|password|tel|url|number)$/.test((target as HTMLInputElement).type ?? ''));
      if (isTextField) return;
      const lowered = e.key.toLowerCase();
      if (lowered === 's') { if (!e.repeat) { pressScanlines('key'); flashEffect('SCANLINES'); } return; }
      if (lowered === 'r') { e.preventDefault(); toggleRecordRef.current(); return; }
      const fx = EFFECTS.find(f => f.key === lowered);
      if (fx) { if (!e.repeat) { pressEffect(fx.id); flashEffect(fx.name); } return; }
      const vjIndex = VJ_KEY_TO_INDEX.get(lowered);
      if (vjIndex !== undefined && vjIndex < videoSources.length) { setActiveVideoIndex(vjIndex); flashChannel(vjIndex); }
      if (lowered === 'f') toggleFullscreen();
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      const lowered = e.key.toLowerCase();
      if (lowered === 's') { releaseScanlines('key'); return; }
      const fx = EFFECTS.find(f => f.key === lowered);
      if (fx) releaseEffect(fx.id);
    };
    const handleBlur = () => { heldEffectsRef.current = []; heldScanlinesRef.current.clear(); setActiveEffect(EFFECT.NONE); setShowScanlines(false); };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('blur', handleBlur);
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp); window.removeEventListener('blur', handleBlur); };
  }, [videoSources.length, isFullscreen]);

  useEffect(() => {
    const el = screenAreaRef.current;
    if (!el || !activeBuffer) return;
    const ar = activeBuffer.width / activeBuffer.height;
    const compute = () => {
      const rect = el.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) return;
      const vw = Math.min(rect.width, rect.height * ar);
      const vh = vw / ar;
      setVideoDisplayWidth(vw);
      setVideoLeftInset((rect.width - vw) / 2);
      setVideoTopInset((rect.height - vh) / 2);
    };
    compute();
    const ro = new ResizeObserver(compute);
    ro.observe(el);
    return () => ro.disconnect();
  }, [activeBuffer, isFullscreen]); // Recalculate on fullscreen toggle

  const toggleFullscreen = () => {
    setIsFullscreen(prev => !prev);
  };

  const setupAudioGraph = () => {
    if (audioCtxRef.current || !audioRef.current) return;
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    const source = ctx.createMediaElementSource(audioRef.current);
    const filter = ctx.createBiquadFilter();
    const analyzer = ctx.createAnalyser();
    const recorderDest = ctx.createMediaStreamDestination();

    filter.type = 'bandpass';
    analyzer.fftSize = 256;

    source.connect(ctx.destination);
    source.connect(filter);
    source.connect(recorderDest); // Capture clean performance audio
    filter.connect(analyzer);

    audioCtxRef.current = ctx;
    sourceNodeRef.current = source;
    filterRef.current = filter;
    analyzerRef.current = analyzer;
    recorderDestRef.current = recorderDest;
  };

  const startLiveAudio = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = ctx.createMediaStreamSource(stream);
      const filter = ctx.createBiquadFilter();
      const analyzer = ctx.createAnalyser();
      const recorderDest = ctx.createMediaStreamDestination();

      filter.type = 'bandpass';
      analyzer.fftSize = 256;
      source.connect(filter);
      source.connect(recorderDest);
      filter.connect(analyzer);

      audioCtxRef.current = ctx;
      analyzerRef.current = analyzer;
      filterRef.current = filter;
      recorderDestRef.current = recorderDest;

      setIsLiveMode(true);
      setIsPlaying(true);
      setAnalysis({ bpm: 0, beats: [], duration: Infinity, peaks: [], audioBuffer: null, settings });
      setTrimRange([0, 0]);
      const dataArray = new Uint8Array(analyzer.frequencyBinCount);
      const history = liveEnergyHistoryRef.current;
      const liveLoop = () => {
        analyzer.getByteFrequencyData(dataArray);
        let sum = 0; for (let i = 0; i < dataArray.length; i++) sum += dataArray[i];
        const energy = sum / dataArray.length / 255;
        history.push(energy); if (history.length > 30) history.shift();
        setCurrentIntensity(energy > 0.02 ? energy : 0);
        if (history.length >= 10) {
          const avg = history.slice(0, -1).reduce((a, b) => a + b, 0) / (history.length - 1);
          const now = performance.now() / 1000;
          if (energy > avg * settings.threshold && energy > 0.04 && now - lastImpulseTimeRef.current > settings.minInterval) {
            lastImpulseTimeRef.current = now;
            const halfDur = pulseDuration / 2; const startTime = now;
            const pulseLoop = () => {
              const elapsed = performance.now() / 1000 - startTime;
              if (elapsed > pulseDuration) { setImpulseProgress(0); return; }
              setImpulseProgress(elapsed < halfDur ? elapsed / halfDur : 1 - (elapsed - halfDur) / halfDur);
              requestAnimationFrame(pulseLoop);
            };
            requestAnimationFrame(pulseLoop);
          }
        }
        liveRafRef.current = requestAnimationFrame(liveLoop);
      };
      liveRafRef.current = requestAnimationFrame(liveLoop);
    } catch (err) { setError('Microphone access denied'); }
  };

  const stopLiveAudio = () => {
    if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
    if (liveRafRef.current) cancelAnimationFrame(liveRafRef.current);
    if (audioCtxRef.current) audioCtxRef.current.close();
    setIsLiveMode(false); setIsPlaying(false); setImpulseProgress(0);
  };

  const processAudioSource = async (url: string, name: string) => {
    try {
      if (isLiveMode) stopLiveAudio();
      setLoading(true); setError(null);
      if (audioRef.current) audioRef.current.pause();
      setIsPlaying(false);
      const result = await engine.current.analyzeMedia(url, settings);
      setAnalysis(result); setTrimRange([0, result.duration]);
      if (audioRef.current) { audioRef.current.src = url; audioRef.current.load(); }
    } catch (err) { setError('Audio analysis failed'); } finally { setLoading(false); }
  };

  const processVideoSource = async (media: any) => {
    try {
      setExtracting(true); setError(null);
      const buffer = await extractFrames(media.dataUrl, setExtractProgress);
      const newSource: VideoSource = {
        id: Math.random().toString(36).substr(2, 9), name: media.name || `Video ${videoSources.length + 1}`,
        buffer, media, segment: { id: Math.random().toString(36).substr(2, 9), start: 0, end: Math.min(1, buffer.duration), speed: 1, isReversed: false },
        thumbnail: generateThumbnail(buffer)
      };
      setVideoSources(prev => { const next = [...prev, newSource]; setActiveVideoIndex(next.length - 1); return next; });
    } catch (err) { setError('Video decode failed'); } finally { setExtracting(false); }
  };

  const handleUseVideoAudio = async () => {
    try {
      const item = await Flow.media.select({ filter: 'video' });
      if (item) {
        const dataUrl = `data:${item.mimeType};base64,${item.base64}`;
        await processAudioSource(dataUrl, item.name);
      }
    } catch (err) {
      console.warn('Video audio selection cancelled');
    }
  };

  const handleSelectVideo = async () => {
    try {
      const item = await Flow.media.select({ filter: 'video' });
      if (item) {
        const dataUrl = `data:${item.mimeType};base64,${item.base64}`;
        await processVideoSource({ dataUrl, name: item.name });
      }
    } catch (err) {
      console.warn('Video selection cancelled or failed');
    }
  };

  const handleDuplicateVideo = (index: number, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    const source = videoSources[index];
    if (!source) return;
    const newSource: VideoSource = {
      ...source,
      id: Math.random().toString(36).substr(2, 9),
      name: `${source.name} (copy)`,
      segment: { ...source.segment, id: Math.random().toString(36).substr(2, 9) }
    };
    setVideoSources(prev => {
      const next = [...prev];
      next.splice(index + 1, 0, newSource);
      return next;
    });
    setActiveVideoIndex(index + 1);
    flashChannel(index + 1);
  };

  const handleRemoveVideo = (index: number, e: React.MouseEvent) => {
    e.stopPropagation();
    setVideoSources(prev => {
      const next = prev.filter((_, i) => i !== index);
      if (activeVideoIndex >= next.length && next.length > 0) {
        setActiveVideoIndex(next.length - 1);
      }
      return next;
    });
  };

  // Recording Implementation
  const toggleRecording = useCallback(async () => {
    if (isRecording) {
      if (recorderRef.current) {
        recorderRef.current.stop();
      }
      return;
    }

    if (!activeBuffer || !canvasRef.current) return;

    // Ensure audio graph is ready
    if (!audioCtxRef.current) setupAudioGraph();
    if (!recorderDestRef.current) {
      setError("Audio context not initialized for recording");
      return;
    }

    try {
      const canvasStream = canvasRef.current.captureStream(30);
      const combinedStream = new MediaStream([
        ...canvasStream.getVideoTracks(),
        ...recorderDestRef.current.stream.getAudioTracks()
      ]);

      const recorder = new MediaRecorder(combinedStream, {
        mimeType: 'video/webm;codecs=vp8,opus'
      });

      recorderChunksRef.current = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) recorderChunksRef.current.push(e.data);
      };

      recorder.onstop = async () => {
        setIsRecording(false);
        setIsSavingRecord(true);
        try {
          const webmBlob = new Blob(recorderChunksRef.current, { type: 'video/webm' });
          const mp4Data = await transcodeWebmToMp4(webmBlob, (p) => setExportProgress(Math.round(p * 100)));

          const reader = new FileReader();
          reader.onloadend = async () => {
            const base64 = (reader.result as string).split(',')[1];
            await Flow.save({ 
              base64, 
              mimeType: 'video/mp4', 
              name: `Performance-${new Date().toISOString().slice(0,19).replace('T','-')}.mp4` 
            });
          };
          reader.readAsDataURL(new Blob([mp4Data], { type: 'video/mp4' }));
        } catch (err) {
          setError("Recording save failed");
          console.error(err);
        } finally {
          setIsSavingRecord(false);
          setExportProgress(0);
        }
      };

      recorderRef.current = recorder;
      recorder.start();
      setIsRecording(true);
    } catch (err) {
      setError("Could not start recorder");
      console.error(err);
    }
  }, [isRecording, activeBuffer]);

  useEffect(() => {
    if (!isPlaying || !analysis || isLiveMode) return;
    setupAudioGraph();
    const analyzer = analyzerRef.current;
    const filter = filterRef.current;
    if (filter) {
      const centerFreq = (settings.lowFreq + settings.highFreq) / 2;
      filter.frequency.value = centerFreq;
      filter.Q.value = centerFreq / (settings.highFreq - settings.lowFreq || 1);
    }
    const dataArray = analyzer ? new Uint8Array(analyzer.frequencyBinCount) : null;
    const halfDur = pulseDuration / 2;
    const loop = () => {
      const t = audioRef.current?.currentTime || 0;
      let videoProgress = 0;
      for (const beat of analysis.beats) {
        if (t >= beat.time - halfDur && t <= beat.time + halfDur) {
          videoProgress = t < beat.time ? (t - (beat.time - halfDur)) / halfDur : 1 - (t - beat.time) / halfDur;
          break;
        }
      }
      setImpulseProgress(Math.max(0, Math.min(1, videoProgress)));
      if (analyzer && dataArray) {
        analyzer.getByteFrequencyData(dataArray);
        let sum = 0; for (let i = 0; i < dataArray.length; i++) sum += dataArray[i];
        setCurrentIntensity(sum / dataArray.length / 255);
      }
      rafRef.current = requestAnimationFrame(loop);
    };
    rafRef.current = requestAnimationFrame(loop);
    return () => { if (rafRef.current) cancelAnimationFrame(rafRef.current); };
  }, [isPlaying, settings, analysis, pulseDuration]);

  const togglePlay = async () => {
    if (isLiveMode) {
      if (!audioCtxRef.current) return;
      if (isPlaying) { await audioCtxRef.current.suspend(); setIsPlaying(false); }
      else { await audioCtxRef.current.resume(); setIsPlaying(true); }
      return;
    }
    if (!audioRef.current || !analysis) return;
    setupAudioGraph();
    if (audioCtxRef.current?.state === 'suspended') await audioCtxRef.current.resume();
    if (isPlaying) { audioRef.current.pause(); setIsPlaying(false); }
    else { try { audioRef.current.currentTime = trimRange[0]; await audioRef.current.play(); setIsPlaying(true); } catch (err) { setError("Playback failed"); } }
  };

  return (
    <>
      <audio ref={audioRef} onTimeUpdate={() => setCurrentTime(audioRef.current?.currentTime || 0)} onEnded={() => setIsPlaying(false)} className="hidden" />
      <input type="file" ref={audioFileInputRef} onChange={(e) => { const f = e.target.files?.[0]; if (f) processAudioSource(URL.createObjectURL(f), f.name); }} accept="audio/*" className="hidden" />

      <div className={`app-shell ${isFullscreen ? 'zen-mode' : ''}`}>
        <div className="main-viewport">
          {!analysis && !loading ? (
            <div className="onboarding-flow">
              <div className="hero-title">
                <div className="empty-state-logo">ribbit</div>
                <div className="hero-subtitle">A BEAT-REACTIVE VJ TOOL FOR LIVE PERFORMANCE</div>
              </div>
              <div className="onboarding-step active">
                <div className="step-number">1</div>
                <div className="step-content">
                  <div className="step-title">add a track with a beat</div>
                  <div className="step-actions">
                    <button className="step-btn primary" onClick={() => audioFileInputRef.current?.click()}><Music size={16} /> upload audio</button>
                    <button className="step-btn primary" onClick={handleUseVideoAudio}><Video size={16} /> use video audio</button>
                  </div>
                </div>
              </div>
            </div>
          ) : !analysis && loading ? (
            <div className="onboarding-flow"><Loader2 className="spinner" size={28} style={{ color: 'var(--accent-dim)' }} /><div>analyzing audio...</div></div>
          ) : (
            <>
              <div className="screen-area" ref={screenAreaRef} onClick={() => activeBuffer && togglePlay()} onDoubleClick={toggleFullscreen}>
                {videoSources.length === 0 && !extracting ? (
                  <div className="video-empty-prompt">
                    <div className="step-number">2</div>
                    <div className="video-empty-grid" onClick={handleSelectVideo}>
                      <div className="video-add-card"><Video size={24} /><span>upload video</span></div>
                    </div>
                  </div>
                ) : extracting ? (
                  <div className="onboarding-flow"><Loader2 className="spinner" size={28} /><div>decoding: {extractProgress}%</div></div>
                ) : activeBuffer ? (
                  <>
                    <TimelinePreview 
                      buffer={activeBuffer} 
                      segments={activeSegments} 
                      impulse={impulseProgress} 
                      intensity={currentIntensity} 
                      isFullscreen={isFullscreen} 
                      effect={activeEffect} 
                      canvasRef={canvasRef}
                    />
                    {showScanlines && <div className="screen-scanlines" />}
                    <div className="screen-vignette" />
                    {videoSources.length > 1 && !isFullscreen && (
                      <div className="channel-indicator" style={{ top: videoTopInset + 10, left: videoLeftInset + 10 }}>
                        <span className="channel-indicator-key">{getVjKey(activeVideoIndex)}</span>
                      </div>
                    )}
                    {channelFlash !== null && <div className={`${isFullscreen ? 'fullscreen-channel-indicator visible' : 'channel-flash-overlay'}`}>{getVjKey(channelFlash)}</div>}
                    {effectFlash && <div className="effect-flash-badge" style={{ top: isFullscreen ? 24 : videoTopInset + 8, right: isFullscreen ? 24 : videoLeftInset + 8 }}>FX · {effectFlash}</div>}
                    <button className="screen-fullscreen-btn" style={{ bottom: isFullscreen ? 24 : videoTopInset + 8, right: isFullscreen ? 24 : videoLeftInset + 8 }} onClick={(e) => { e.stopPropagation(); toggleFullscreen(); }}>{isFullscreen ? <X size={16} /> : <Maximize size={16} />}</button>
                    {!isPlaying && !isFullscreen && <div className="screen-play-overlay"><button className="transport-play-btn"><Play size={28} /></button></div>}
                  </>
                ) : null}
              </div>

              {!isFullscreen && (
                <div className="waveform-strip">
                  <div className="waveform-strip-inner" style={{ width: videoDisplayWidth || '100%' }}>
                    <WaveformVisualizer analysis={analysis} currentTime={currentTime} trimRange={trimRange} onTrimChange={setTrimRange} onSeek={(t) => { if (audioRef.current) audioRef.current.currentTime = t; }} />
                    <div className="waveform-info-bar">
                      <div className="waveform-bpm"><span className="bpm-value">{analysis?.bpm || '--'}</span><span className="bpm-label">bpm</span>
                        <button className={`detection-gear-btn ${showDetectionDrawer ? 'active' : ''}`} onClick={() => setShowDetectionDrawer(v => !v)}><Settings size={14} /></button>
                        {showDetectionDrawer && <div className="detection-popover"><SettingsPanel settings={settings} onChange={setSettings} disabled={loading} /></div>}
                      </div>
                      <div className="energy-row">
                        <div className="energy-blocks">{Array.from({ length: 12 }).map((_, i) => (<div key={i} className={`block ${i < Math.round(currentIntensity * 12) ? 'lit' : ''}`} />))}</div>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </>
          )}
        </div>

        {!extracting && !isFullscreen && (
          <div className="sidebar custom-scrollbar">
            <div className="ribbit-logo">
              <div className="ribbit-wordmark">ribbit</div>
              <div className="lcd-display"><span className="lcd-text">{activeVideo ? activeVideo.name : 'no video'}</span></div>
            </div>

            <div className="sidebar-group">
              <div className="sidebar-group-header">video</div>
              <div className="sidebar-section">
                <div className="section-header"><span>channels</span></div>
                <div className="section-body">
                  <div className="channel-grid">
                    {videoSources.map((vs, i) => (
                      <div key={vs.id} className={`channel-item ${i === activeVideoIndex ? 'active' : ''}`} onClick={() => { setActiveVideoIndex(i); flashChannel(i); }}>
                        <img src={vs.thumbnail} alt={vs.name} />
                        <div className="channel-actions">
                          <button className="channel-action-btn" onClick={(e) => handleDuplicateVideo(i, e)} title="Duplicate"><Copy size={8} /></button>
                          <button className="channel-action-btn delete" onClick={(e) => handleRemoveVideo(i, e)} title="Remove"><X size={10} /></button>
                        </div>
                      </div>
                    ))}
                    <button className="channel-add" onClick={handleSelectVideo}><Plus size={14} /></button>
                  </div>
                </div>
              </div>

              {activeVideo && (
                <div className="sidebar-section clip-inspector">
                  <div className="section-header"><span>clip <span className="scope-badge channel">ch {getVjKey(activeVideoIndex)}</span></span></div>
                  <div className="section-body">
                    <SegmentItem segment={activeVideo.segment} index={activeVideoIndex} maxDuration={activeVideo.buffer.duration} onRemove={() => setVideoSources(v => v.filter((_, i) => i !== activeVideoIndex))} onDuplicate={() => handleDuplicateVideo(activeVideoIndex)} onUpdate={(_, u) => setVideoSources(v => v.map((vs, i) => i === activeVideoIndex ? { ...vs, segment: { ...vs.segment, ...u } } : vs))} />
                  </div>
                </div>
              )}

              <div className="sidebar-section">
                <div className="section-header"><span>effects</span></div>
                <div className="section-body">
                  <div className="fx-list">
                    <div className={`fx-item ${showScanlines ? 'active' : ''}`} onMouseDown={() => { pressScanlines('mouse'); flashEffect('SCANLINES'); window.addEventListener('mouseup', () => releaseScanlines('mouse'), { once: true }); }}><span className="fx-name">scanlines</span><span className="fx-key">S</span></div>
                    {EFFECTS.map(fx => (
                      <div key={fx.id} className={`fx-item ${activeEffect === fx.id ? 'active' : ''}`} onMouseDown={() => { pressEffect(fx.id); flashEffect(fx.name); window.addEventListener('mouseup', () => releaseEffect(fx.id), { once: true }); }}><span className="fx-name">{fx.name.toLowerCase()}</span><span className="fx-key">{fx.key.toUpperCase()}</span></div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {error && <div className="error-toast">{error}</div>}

            <div className="sidebar-record-section">
              <span className="sidebar-record-label">performance rec</span>
              <button 
                className={`record-btn ${isRecording ? 'active' : ''}`} 
                onClick={toggleRecording}
                disabled={isSavingRecord}
                title="Toggle Recording (R)"
              >
                {isSavingRecord ? (
                  <Loader2 className="spinner" size={24} />
                ) : isRecording ? (
                  <Square size={20} fill="currentColor" />
                ) : (
                  <Circle size={24} fill="currentColor" />
                )}
              </button>
              {isSavingRecord && <div style={{ fontSize: '9px', color: 'var(--accent)', marginTop: 4 }}>saving: {exportProgress}%</div>}
            </div>

            <div className="sidebar-keys">
              <div className="keys-row"><span className="keys-key">1-0</span><span>switch video</span></div>
              <div className="keys-row"><span className="keys-key">R</span><span>toggle record</span></div>
            </div>
          </div>
        )}
      </div>
      <VfxPanel />
    </>
  );
};

export default App;
